const payload = $input.first().json.body || $input.first().json;

const service = payload.service || payload.labels?.service || 'unknown-service';
const severityRaw = (payload.severity || payload.labels?.severity || payload.priority || 'warning').toString().toLowerCase();
const errorMessage = payload.message || payload.annotations?.summary || payload.title || 'No error message provided';
const errorSignature = (payload.errorSignature || payload.fingerprint || `${service}:${errorMessage}`).slice(0, 160);

const severityMap = { critical: 90, high: 75, warning: 50, low: 25, info: 10 };
const severityScore = severityMap[severityRaw] ?? 50;

// Simple deterministic hash (avoids needing external crypto module in the sandbox)
function simpleHash(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16);
}
const dedupeKey = simpleHash(errorSignature);

// Recurrence tracking across executions using workflow static data
const staticData = $getWorkflowStaticData('node');
if (!staticData.incidents) staticData.incidents = {};
const existing = staticData.incidents[dedupeKey];
const occurrenceCount = existing ? existing.count + 1 : 1;
staticData.incidents[dedupeKey] = { count: occurrenceCount, lastSeen: new Date().toISOString(), service };

// Only these services are trusted for unsupervised auto-remediation, and never at the top severity tier
const AUTO_REMEDIATION_ALLOWLIST = ['checkout-service', 'payments-api', 'auth-service', 'notification-worker'];
const autoRemediationEligible = AUTO_REMEDIATION_ALLOWLIST.includes(service) && severityScore < 90;

return [{
  json: {
    service,
    severityRaw,
    severityScore,
    errorMessage,
    errorSignature,
    dedupeKey,
    occurrenceCount,
    isRecurring: occurrenceCount > 1,
    autoRemediationEligible,
    receivedAt: new Date().toISOString(),
    rawPayload: payload
  }
}];

