const aiResponse = $input.first().json;
const alert = $('Code 1 - Parse, Classify & Deduplicate Alert').first().json;

let rca;
try {
  const rawText = aiResponse.content?.[0]?.text || aiResponse.completion || '{}';
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  rca = JSON.parse(cleaned);
} catch (e) {
  rca = { rootCause: 'Unable to parse AI response', confidenceScore: 0, riskLevel: 'high', suggestedFixSummary: '', filesLikelyAffected: [], cursorInstructions: '' };
}

const MIN_CONFIDENCE_FOR_AUTOFIX = 70;
const autoFixApproved = alert.autoRemediationEligible
  && (rca.confidenceScore ?? 0) >= MIN_CONFIDENCE_FOR_AUTOFIX
  && rca.riskLevel !== 'high';

return [{
  json: {
    ...alert,
    rootCause: rca.rootCause,
    confidenceScore: rca.confidenceScore ?? 0,
    riskLevel: rca.riskLevel || 'high',
    suggestedFixSummary: rca.suggestedFixSummary || '',
    filesLikelyAffected: rca.filesLikelyAffected || [],
    cursorInstructions: rca.cursorInstructions || rca.suggestedFixSummary || '',
    autoFixApproved
  }
}];

const agentResponse = $input.first().json;
const context = $('Code 2 - Parse RCA & Decide Remediation Path').first().json;

const prUrl = agentResponse.pullRequestUrl || agentResponse.pr_url || null;
const testsPassed = agentResponse.testsPassed ?? agentResponse.tests_passed ?? false;
const deployed = agentResponse.deployed ?? agentResponse.autoMerged ?? agentResponse.auto_merged ?? false;

let resolutionStatus = 'Needs Manual Review';
if (prUrl && testsPassed && deployed) resolutionStatus = 'Auto-Resolved & Deployed';
else if (prUrl && testsPassed) resolutionStatus = 'Fix Ready - Awaiting Merge';
else if (prUrl) resolutionStatus = 'PR Opened - Tests Failed';
else resolutionStatus = 'Agent Did Not Produce a Fix';

return [{
  json: {
    ...context,
    path: 'auto-fix',
    prUrl,
    testsPassed,
    deployed,
    resolutionStatus,
    resolvedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;

const reasons = [];
if (!item.autoRemediationEligible) reasons.push('Service is not on the auto-remediation allowlist, or severity is too high for unsupervised action.');
if ((item.confidenceScore ?? 0) < 70) reasons.push(`AI confidence too low (${item.confidenceScore}%).`);
if (item.riskLevel === 'high') reasons.push('AI assessed the fix as high risk.');
if (reasons.length === 0) reasons.push('Did not meet auto-fix criteria.');

return [{
  json: {
    ...item,
    path: 'escalation',
    resolutionStatus: 'Escalated to On-Call',
    escalationReasons: reasons,
    resolvedAt: new Date().toISOString()
  }
}];

